package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

/**
 * Giving the selected people a grade together, from a date (null: the sheet's today). Each is edited
 * on its own, as the person form would, keeping their name and own terms, in list order: the people by
 * their position. A person who cannot be edited (or is not on the sheet) is left as they
 * are, writing nothing; the others are still edited. For a viewer, nobody is edited.
 */
@Service
public class BulkGradeService {

    private final PersonService service;
    private final PersonRepository people;
    private final RoleService roles;

    public BulkGradeService(PersonService service, PersonRepository people, RoleService roles) {
        this.service = service;
        this.people = people;
        this.roles = roles;
    }

    /** Give the selected people the grade from the date: the people changed, in the order they were changed. */
    public List<Person> grade(String sheetId, String user, Collection<Long> personIds, String grade, LocalDate from) {
        Set<Long> selected = new HashSet<>(personIds);
        List<Person> changed = new ArrayList<>();
        if (Role.VIEWER.equals(roles.roleOf(sheetId, user))) {
            return changed;
        }
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            if (!selected.contains(person.getId())) {
                continue;
            }
            try {
                changed.add(service.edit(sheetId, user, person.getId(), person.getVersion(), person.getName(), grade,
                        from, person.getTerms(), person.getContact(),
                        false, false));
            } catch (ResponseStatusException refused) {
                // left as they are: their edit wrote nothing
            }
        }
        return changed;
    }
}
            @Size(max = 200) String contact,
            boolean termsGiven,
            boolean contactGiven,
            Long version) {
    }

    /** The people selected to be given a grade together, the grade, and the date it is in force from (none: the sheet's today). */
    public record BulkGradeForm(
            @NotNull @Size(min = 1, max = 1000) List<@NotNull Long> personIds,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate from) {
    }

    /** The import box's text: lines of name,grade,terms,contact. */
    public record ImportForm(@NotNull @Size(max = 200_000) String text) {
    }

    private final PersonService service;
    private final ImportService imports;
    private final BulkGradeService bulkGrade;
    private final WatchService watches;
    private final MergeService merges;
    private final TransferService transfers;
    private final SheetHistory history;

    public PersonController(PersonService service, ImportService imports, BulkGradeService bulkGrade, WatchService watches,
            MergeService merges, TransferService transfers, SheetHistory history) {
        this.service = service;
        this.imports = imports;
        this.bulkGrade = bulkGrade;
        this.watches = watches;
        this.merges = merges;
        this.transfers = transfers;
        this.history = history;
    }

    /** The sheet's people in list order; with an as-of date, as they stood at the end of it. */
    @GetMapping
    public List<PersonView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) String asOf) {
        return history.views(sheetId, AsOfGuard.date(asOf)).map(SheetHistory.Views::people)
                .orElseGet(() -> {
                    Set<Long> clashing = service.clashing(sheetId);
                    return service.list(sheetId).stream()
                            .map(person -> PersonView.of(person, clashing.contains(person.getId()))).toList();
                });
    }

    /** Add a person to the sheet. */
    @PostMapping
    public PersonView add(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid PersonForm form) {
        return view(service.add(sheetId, SignedIn.name(user), form.name(), form.grade(), form.terms(),
